const builtInNationalHolidays = {
  IN:{'01-26':'Republic Day','08-15':'Independence Day','10-02':'Gandhi Jayanti'}
};

const state = { language:'en', selected:[], date:'', duration:60, slot:20, holidays:new Map(), suggestions:[], restoredFromUrl:false, holidayCheckId:0 };
const els = Object.fromEntries(['language','city-list','city-search','city-search-label','city-suggestions','city-error','add-city','meeting-date','duration','results','result-label','results-title','meeting-summary','compromise-note','selected-day','time-slider','timeline','holiday-notices','copy-result','share-result','previous-day','next-day','earlier','later','theme-toggle'].map(id => [id.replaceAll('-','_'), document.getElementById(id)]));

function t(key){ return qualityCopy[state.language]?.[key] || positioningCopy[state.language]?.[key] || pageCopy[state.language]?.[key] || copy[state.language]?.[key] || qualityCopy.en[key] || positioningCopy.en[key] || pageCopy.en[key] || copy.en[key] || key; }
function track(event, detail={}){ window.dataLayer?.push({event, ...detail}); window.dispatchEvent(new CustomEvent('commonhours:analytics',{detail:{event,...detail}})); }
function localParts(date, zone){ return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(p=>p.type!=='literal').map(p=>[p.type,p.value])); }
function offsetAt(date, zone){ const p=localParts(date,zone); return Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute)-date.getTime(); }
function zonedMidnight(dateText, zone){ const [y,m,d]=dateText.split('-').map(Number); const guess=new Date(Date.UTC(y,m-1,d,0,0)); return new Date(guess.getTime()-offsetAt(guess,zone)); }
function formatTime(date, zone){ return new Intl.DateTimeFormat(state.language,{timeZone:zone,hour:'numeric',minute:'2-digit'}).format(date); }
function formatDay(date, zone){ return new Intl.DateTimeFormat(state.language,{timeZone:zone,weekday:'short',month:'short',day:'numeric'}).format(date); }
function isoLocal(date, zone){ const p=localParts(date,zone); return `${p.year}-${p.month}-${p.day}`; }
function slotDate(slot){ const start=zonedMidnight(state.date,state.selected[0].zone); return new Date(start.getTime()+slot*30*60000); }
function isWorking(date, city, duration=state.duration){ const p=localParts(date,city.zone); const minutes=+p.hour*60 + +p.minute; return !['Sat','Sun'].includes(p.weekday) && minutes>=540 && minutes+duration<=1020; }

function renderCities(){
  const now=new Date();
  els.city_list.innerHTML=state.selected.map((city,index)=>`<div class="city-row"><div class="city-name"><strong>${city.name}</strong><span>${city.country?`${city.country} · `:''}${city.zone}</span></div><div class="city-clock"><strong>${formatTime(now,city.zone)}</strong><span>${index===0?'Your reference':'Local time now'}</span></div><button class="remove-city" type="button" data-remove="${index}" aria-label="Remove ${city.name}">×</button></div>`).join('');
  els.city_search_label.textContent=state.selected.length?t('addCity'):t('startCity');
  if(typeof renderWorldMap==='function') renderWorldMap();
}
function setLanguage(lang){ state.language=copy[lang]?lang:'en'; document.documentElement.lang=state.language; els.language.value=state.language; document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)}); document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder)}); renderCities(); if(state.selected.length>=2) renderResults(); localStorage.setItem('commonHoursLanguage',state.language); }
function applyTheme(theme){ document.documentElement.dataset.theme=theme; localStorage.setItem('commonHoursTheme',theme); }

function saveCities(){ localStorage.setItem('commonHoursCitiesV2',JSON.stringify(state.selected)); }
function meetingUrl(){
  const url=new URL(location.href); url.search=''; url.hash='';
  state.selected.forEach(city=>url.searchParams.append('city',[city.name,city.zone,city.countryCode||'',city.subdivision||'',city.country||''].join('|')));
  url.searchParams.set('date',state.date); url.searchParams.set('duration',String(state.duration)); url.searchParams.set('slot',String(state.slot));
  if(state.language!=='en') url.searchParams.set('lang',state.language);
  return url;
}
function updateMeetingUrl(){ if(state.selected.length>=2) history.replaceState(null,'',meetingUrl()); }
function restoreFromUrl(){
  const params=new URLSearchParams(location.search); const encoded=params.getAll('city');
  if(encoded.length<1) return false;
  const restored=encoded.slice(0,5).map(value=>{ const [name,zone,countryCode,subdivision,country]=value.split('|'); return {name,zone,countryCode:countryCode||null,subdivision:subdivision||null,country:country||''}; }).filter(city=>city.name&&city.zone);
  if(restored.length<1) return false;
  state.selected=restored;
  const date=params.get('date'); if(/^\d{4}-\d{2}-\d{2}$/.test(date||'')) state.date=date;
  const duration=Number(params.get('duration')); if([30,45,60,90,120].includes(duration)) state.duration=duration;
  const slot=Number(params.get('slot')); if(Number.isInteger(slot)&&slot>=0&&slot<=47) state.slot=slot;
  const lang=params.get('lang'); if(copy[lang]) state.language=lang;
  state.restoredFromUrl=true; saveCities(); return true;
}
function shareText(){ return `${els.result_label.textContent}: ${els.results_title.textContent} — ${els.meeting_summary.textContent}\n\n${meetingUrl().href}`; }
function addSelectedCity(city){
  if(state.selected.some(item=>item.name===city.name && item.zone===city.zone)){ els.city_error.textContent='Already added.'; return; }
  if(state.selected.length>=5){ els.city_error.textContent='Maximum 5 cities.'; return; }
  state.selected.push(city); saveCities(); els.city_search.value=''; els.city_error.textContent=''; els.city_suggestions.hidden=true; renderCities();
  if(state.selected.length>=2) calculate(); else els.results.hidden=true;
  track('city_added',{city:city.name,country:city.countryCode||''});
}

const COUNTRY_BY_CODE = (()=>{ const map={};
  Object.keys(COUNTRY_CITIES).forEach(key=>{ const entry=COUNTRY_CITIES[key];
    if(entry[1] && !map[entry[1]]) map[entry[1]]=entry[0]; });
  return map; })();

function placeDetail(city){
  // Open-Meteo omits `country` for territories such as PR, GU and VI, which left
  // rows showing only a municipality name. Recover it from the country code.
  const country=city.country || COUNTRY_BY_CODE[city.countryCode] || '';
  const admin=(city.admin && city.admin!==city.name) ? city.admin : '';
  return [admin,country].filter(Boolean).join(' · ') || city.zone || '';
}

function zoneNow(zone){
  if(!zone) return {time:'',abbr:''};
  try{
    const now=new Date();
    const time=new Intl.DateTimeFormat(state.language||'en',{timeZone:zone,hour:'numeric',minute:'2-digit'}).format(now);
    const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'short'}).formatToParts(now);
    const abbr=(parts.find(part=>part.type==='timeZoneName')||{}).value||'';
    return {time,abbr};
  }catch(error){ return {time:'',abbr:''}; }
}

function localPlaceLookup(query){
  const region=REGION_CITIES[query];
  if(region) return {label:region[0][1],
    items:region.map(row=>({name:row[0],admin:row[1],country:row[2],zone:row[3],countryCode:row[4],subdivision:null}))};
  const country=COUNTRY_CITIES[query];
  if(country) return {label:country[0],
    items:country[2].map(row=>({name:row[0],admin:'',country:country[0],zone:row[1],countryCode:country[1],subdivision:null}))};
  return {label:'',items:[]};
}

function dedupePlaces(list){
  return list.filter((city,index,array)=>array.findIndex(item=>item.name===city.name&&item.zone===city.zone)===index);
}

function renderSuggestions(items,status=''){
  els.city_suggestions.replaceChildren();
  if(status){ const line=document.createElement('div'); line.className='city-suggestions-status'; line.textContent=status; els.city_suggestions.append(line); }
  items.forEach((city,index)=>{
    const button=document.createElement('button'); button.type='button'; button.className='city-suggestion'; button.role='option'; button.dataset.suggestion=String(index);
    const main=document.createElement('div'); main.className='city-suggestion-main';
    const name=document.createElement('strong'); name.textContent=city.name;
    const detail=document.createElement('span'); detail.textContent=placeDetail(city);
    main.append(name,detail);
    const clock=document.createElement('div'); clock.className='city-suggestion-time';
    const now=zoneNow(city.zone);
    const time=document.createElement('strong'); time.textContent=now.time;
    const abbr=document.createElement('span'); abbr.textContent=now.abbr;
    clock.append(time,abbr);
    button.append(main,clock); button.title=city.zone||'';
    els.city_suggestions.append(button);
  });
  els.city_suggestions.hidden=!status && items.length===0;
}

let searchTimer; let searchController;
async function searchPlaces(query){
  const normalized=query.trim();
  if(normalized.length<2){ state.suggestions=[]; renderSuggestions([]); return; }
  const lower=normalized.toLowerCase();
  const lookup=localPlaceLookup(lower);
  const region=lookup.items;
  const regionLabel=region.length?t('citiesIn').replace('{region}',lookup.label):'';
  const local=cities.filter(city=>`${city.name} ${city.country}`.toLowerCase().includes(lower)).slice(0,5).map(city=>({...city,admin:''}));
  const seed=dedupePlaces([...region,...local]).slice(0,8);
  state.suggestions=seed; renderSuggestions(seed,seed.length?regionLabel||t('searching'):t('searching'));
  searchController?.abort(); searchController=new AbortController();
  try{
    const response=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(normalized)}&count=30&language=${state.language}&format=json`,{signal:searchController.signal});
    if(!response.ok) throw new Error('Search unavailable');
    const data=await response.json();
    const remote=(data.results||[])
      .filter(place=>place.timezone && (!place.feature_code || /^PPL/.test(place.feature_code)))
      .sort((a,b)=>(b.population||0)-(a.population||0))
      .map(place=>({name:place.name,country:place.country||'',admin:place.admin1||'',zone:place.timezone,countryCode:place.country_code||null,subdivision:null,lat:typeof place.latitude==='number'?place.latitude:null,lon:typeof place.longitude==='number'?place.longitude:null}));
    const combined=dedupePlaces([...region,...local,...remote]).slice(0,8);
    state.suggestions=combined; renderSuggestions(combined,combined.length?regionLabel:t('noMatches'));
  }catch(error){ if(error.name!=='AbortError'){ const fallback=dedupePlaces([...region,...local]).slice(0,8); state.suggestions=fallback; renderSuggestions(fallback,fallback.length?regionLabel:t('noMatches')); } }
}

const ZONE_ALIASES={'Asia/Calcutta':'Asia/Kolkata','Asia/Saigon':'Asia/Ho_Chi_Minh','Asia/Katmandu':'Asia/Kathmandu',
  'Asia/Rangoon':'Asia/Yangon','Asia/Ulan_Bator':'Asia/Ulaanbaatar','Asia/Macao':'Asia/Macau','Asia/Dacca':'Asia/Dhaka',
  'Asia/Thimbu':'Asia/Thimphu','Asia/Ashkhabad':'Asia/Ashgabat','Asia/Istanbul':'Europe/Istanbul','Europe/Kiev':'Europe/Kyiv',
  'America/Buenos_Aires':'America/Argentina/Buenos_Aires','America/Godthab':'America/Nuuk','Atlantic/Faeroe':'Atlantic/Faroe',
  'Africa/Asmera':'Africa/Asmara','Pacific/Ponape':'Pacific/Pohnpei','Pacific/Truk':'Pacific/Chuuk','Pacific/Enderbury':'Pacific/Kanton',
  'America/Indianapolis':'America/Indiana/Indianapolis','America/Louisville':'America/Kentucky/Louisville','Europe/Nicosia':'Asia/Nicosia'};
function canonicalZone(zone){ return ZONE_ALIASES[zone]||zone; }

function detectReferenceCity(){
  // The row renderer and the localStorage restore already understand `detected`
  // rows (label "Your time zone", never persisted). This is the missing producer:
  // map the browser's zone to the best-known city in that zone. A wrong guess
  // (VPN, travel) is one click to remove and is never saved.
  let zone='';
  try{ zone=Intl.DateTimeFormat().resolvedOptions().timeZone||''; }catch(error){ zone=''; }
  if(!zone) return null;
  // Chromium reports legacy IANA names (Asia/Calcutta) while our data uses the current
  // ones (Asia/Kolkata); compare both sides through the same canonical form.
  const same=(a,b)=>canonicalZone(a)===canonicalZone(b);
  if(state.selected.some(city=>same(city.zone,zone))) return null;
  const seed=cities.find(city=>same(city.zone,zone));
  if(seed) return {...seed,admin:'',detected:true};
  for(const key of Object.keys(COUNTRY_CITIES)){
    const entry=COUNTRY_CITIES[key]; const hit=entry[2].find(row=>same(row[1],zone));
    if(hit) return {name:hit[0],country:entry[0],countryCode:entry[1],zone:hit[1],subdivision:null,admin:'',detected:true};
  }
  for(const key of Object.keys(REGION_CITIES)){
    const hit=REGION_CITIES[key].find(row=>same(row[3],zone));
    if(hit) return {name:hit[0],country:hit[2],countryCode:hit[4],zone:hit[3],subdivision:null,admin:hit[1],detected:true};
  }
  return null;
}

// Intl only ever gives a TIME ZONE, which IANA names after one representative
// city per zone - "America/New_York" covers the whole US Eastern zone, not
// literally New York. detectReferenceCity() above is the honest baseline: the
// best-known city for that zone. This upgrades the DISPLAY NAME with real
// IP-based geolocation from a Worker that echoes Cloudflare's own per-request
// edge data - no new dependency, no key, and no delay to the initial render:
// it runs after the page has already shown the zone-based guess, and only
// touches the name if it resolves in time and agrees with the browser's own
// zone. The zone driving the actual meeting-time math never changes here.
async function upgradeDetectedCityWithGeo(browserZone){
  const endpoint=(document.body.dataset.geoEndpoint||'').trim();
  if(!endpoint) return;
  let data;
  try{
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),1500);
    const response=await fetch(endpoint,{signal:controller.signal,cache:'no-store'});
    clearTimeout(timer);
    if(!response.ok) return;
    data=await response.json();
  }catch(error){ return; }
  if(!data||!data.city||!data.timezone) return;
  // If the IP-derived zone disagrees with the device's own clock (VPN, travel,
  // a stale system setting, or the edge geo database simply being wrong for
  // that IP), showing its city name next to a different zone would be worse
  // than the honest zone-only guess - so only upgrade when they agree.
  if(canonicalZone(data.timezone)!==canonicalZone(browserZone)) return;
  const index=state.selected.findIndex(city=>city.detected);
  if(index===-1) return; // the user already removed or replaced the detected row
  if(canonicalZone(state.selected[index].zone)!==canonicalZone(browserZone)) return;
  state.selected[index]={...state.selected[index],name:data.city,admin:data.region||'',
    country:COUNTRY_BY_CODE[data.countryCode]||state.selected[index].country,
    countryCode:data.countryCode||state.selected[index].countryCode};
  renderCities();
  if(state.selected.length>=2) calculate();
}

function restoreOrDetectReference(){
  const fromUrl=restoreFromUrl();
  if(!fromUrl){
    try{
      const saved=JSON.parse(localStorage.getItem('commonHoursCitiesV2')||'[]');
      if(Array.isArray(saved)&&saved.length) state.selected=saved.filter(city=>city?.zone&&city?.name&&!city.detected).slice(0,5);
    }catch(error){}
  }
  // Re-detect whenever no detected row is present - NOT merely "fewer than two
  // cities". With three or more cities saved (the detected one plus two others
  // the visitor added), the filter above strips the detected one down to two
  // real cities, which used to read as "already have enough" and silently
  // skipped detection: the visitor's own city never came back on a return
  // visit. The one exception is a link that already names two or more cities -
  // a fully-specified shared link should not be silently modified by adding
  // whoever happens to be viewing it.
  const skipDetection=fromUrl&&state.selected.length>=2;
  if(!skipDetection&&!state.selected.some(city=>city.detected)){
    const detected=detectReferenceCity();
    if(detected){
      state.selected.unshift(detected); state.selected=state.selected.slice(0,5);
      // a URL carrying one city plus the detected one is a fresh pair: find the best slot
      if(fromUrl) state.restoredFromUrl=false;
      upgradeDetectedCityWithGeo(detected.zone); // fire-and-forget; never blocks the initial render
    }
  }
}

function findBestSlot(){
  const needed=Math.ceil(state.duration/30);
  let best={slot:20,score:-1,perfect:false};
  for(let slot=0;slot<=48-needed;slot++){
    let score=0; let perfect=true;
    for(const city of state.selected){
      for(let part=0;part<needed;part++){
        const good=isWorking(slotDate(slot+part),city,30);
        score+=good?1:0; perfect&&=good;
      }
    }
    if(perfect) return {slot,score,perfect:true};
    if(score>best.score) best={slot,score,perfect:false};
  }
  return best;
}
function slotIsPerfect(){
  const needed=Math.ceil(state.duration/30);
  return state.selected.every(city=>Array.from({length:needed},(_,part)=>isWorking(slotDate(state.slot+part),city,30)).every(Boolean));
}

let fallbackHolidaysPromise=null;
function loadFallbackHolidays(){
  // Static list generated by tools/gen_holidays.py for countries the live API does not cover.
  // no-cache = revalidate against GitHub Pages' ETag, so a regenerated file is picked up promptly.
  if(!fallbackHolidaysPromise){
    fallbackHolidaysPromise=fetch('holidays-fallback.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null).catch(()=>null);
  }
  return fallbackHolidaysPromise;
}

async function holidayFor(city,date){
  if(!city.countryCode) return false;
  const localDate=isoLocal(date,city.zone); const year=localDate.slice(0,4); const key=`${city.countryCode}-${year}`;
  const fixedHoliday=builtInNationalHolidays[city.countryCode]?.[localDate.slice(5)];
  if(fixedHoliday) return {name:fixedHoliday,nationalHoliday:true,builtIn:true};
  if(!state.holidays.has(key)){
    let list=false;
    try{
      const response=await fetch(`https://nagerholidays.com/api/v4/Holidays/${city.countryCode}/${year}`);
      if(!response.ok) throw new Error('Holiday data unavailable');
      const data=await response.json();
      if(Array.isArray(data)&&data.length) list=data;
    }catch{ list=false; }
    if(list===false){
      // The live API has nothing for countries whose holidays are announced rather than fixed
      // (moon sighting, decrees, lunar calendars). Use the generated list, only for years it covers.
      const fallback=await loadFallbackHolidays();
      const rows=fallback&&fallback.countries&&fallback.countries[city.countryCode];
      if(rows&&Array.isArray(fallback.years)&&fallback.years.includes(Number(year))) list=rows.filter(h=>h.date.slice(0,4)===year);
    }
    state.holidays.set(key,list);
  }
  const holidays=state.holidays.get(key);
  if(holidays===false) return false;
  return holidays.find(h=>h.date===localDate && (h.nationalHoliday || !h.subdivisionCodes?.length || h.subdivisionCodes.includes(city.subdivision))) || null;
}

function renderResults(isCompromise=!slotIsPerfect()){
  if(state.selected.length<2){ els.results.hidden=true; return; }
  els.results.hidden=false;
  const start=slotDate(state.slot); const end=new Date(start.getTime()+state.duration*60000);
  els.result_label.textContent=t(isCompromise?'bestCompromise':'bestOverlap');
  els.results_title.textContent=`${formatTime(start,state.selected[0].zone)}–${formatTime(end,state.selected[0].zone)} ${state.selected[0].name}`;
  els.meeting_summary.textContent=state.selected.map(c=>`${formatTime(start,c.zone)} ${c.name}`).join(' · ');
  els.compromise_note.hidden=!isCompromise; els.compromise_note.textContent=isCompromise?t('compromiseHint'):'';
  els.selected_day.textContent=formatDay(start,state.selected[0].zone);
  els.time_slider.value=state.slot;
  const width=Math.max(2,(state.duration/1440)*100); const left=(state.slot/48)*100;
  els.timeline.innerHTML=state.selected.map(city=>{
    const slots=Array.from({length:48},(_,slot)=>`<span class="slot ${isWorking(slotDate(slot),city,30)?'working':''}"></span>`).join('');
    return `<div class="timeline-row"><div class="timeline-city"><strong>${city.name}</strong><span>${formatDay(start,city.zone)} · ${formatTime(start,city.zone)}</span></div><div class="timeline-track" data-track><div class="slot-grid">${slots}</div><span class="meeting-band" style="left:${left}%;width:${width}%"></span></div></div>`;
  }).join('');
  document.querySelectorAll('.slot-grid').forEach(grid=>{ grid.style.display='grid'; grid.style.gridTemplateColumns='repeat(48,1fr)'; grid.style.position='absolute'; grid.style.inset='0'; });
  renderWorldMap();
  updateMeetingUrl();
  checkHolidays(start);
}

async function checkHolidays(start){
  const checkId=++state.holidayCheckId;
  els.holiday_notices.innerHTML=`<div class="holiday-notice status-loading">◌ ${t('checkingHolidays')}</div>`;
  const notices=[];
  for(const city of state.selected){
    const parts=localParts(start,city.zone);
    const holiday=await holidayFor(city,start);
    if(holiday) notices.push({kind:'warning',icon:'⚑',text:`${city.name}: ${t('holiday')} — ${holiday.name}${holiday.estimated?` (${t('holidayEstimated')})`:''}`});
    else if(['Sat','Sun'].includes(parts.weekday)) notices.push({kind:'warning',icon:'●',text:`${city.name}: ${t('weekend')}`});
    else if(holiday===false) notices.push({kind:'muted',icon:'○',text:`${city.name}: ${t('holidayUnavailable')}`});
    else notices.push({kind:'ok',icon:'✓',text:`${city.name}: ${t('workingDay')}`});
  }
  if(checkId!==state.holidayCheckId) return;
  els.holiday_notices.innerHTML=notices.map(n=>`<div class="holiday-notice status-${n.kind}">${n.icon} ${n.text}</div>`).join('');
}

function calculate(){ if(state.selected.length<2){ els.city_error.textContent=t('minimumCities'); els.results.hidden=true; return; } els.city_error.textContent=''; const best=findBestSlot(); state.slot=best.slot; renderResults(!best.perfect); track('overlap_calculated',{cities:state.selected.length,duration:state.duration}); }
function shiftDay(amount){ const d=new Date(`${state.date}T12:00:00Z`); d.setUTCDate(d.getUTCDate()+amount); state.date=d.toISOString().slice(0,10); els.meeting_date.value=state.date; calculate(); }
function shiftTime(amount){ state.slot=Math.max(0,Math.min(47,state.slot+amount)); renderResults(); track('time_adjusted',{slot:state.slot}); }

els.city_search.addEventListener('input',()=>{ clearTimeout(searchTimer); searchTimer=setTimeout(()=>searchPlaces(els.city_search.value),220); });
els.city_search.addEventListener('focus',()=>{ if(state.suggestions.length) renderSuggestions(state.suggestions); });
els.city_suggestions.addEventListener('click',event=>{ const button=event.target.closest('[data-suggestion]'); if(button) addSelectedCity(state.suggestions[Number(button.dataset.suggestion)]); });
els.add_city.addEventListener('click',()=>{ if(state.suggestions.length) addSelectedCity(state.suggestions[0]); else { els.city_error.textContent=t('selectCity'); searchPlaces(els.city_search.value); } });
els.city_list.addEventListener('click',event=>{ const button=event.target.closest('[data-remove]'); if(!button)return; state.selected.splice(Number(button.dataset.remove),1); saveCities(); renderCities(); if(state.selected.length>=2) calculate(); else els.results.hidden=true; });
els.meeting_date.addEventListener('change',()=>{state.date=els.meeting_date.value;calculate();});
els.duration.addEventListener('change',()=>{state.duration=Number(els.duration.value);calculate();track('duration_changed',{duration:state.duration});});
els.time_slider.addEventListener('input',()=>{state.slot=Number(els.time_slider.value);renderResults();});
els.earlier.addEventListener('click',()=>shiftTime(-1)); els.later.addEventListener('click',()=>shiftTime(1));
els.previous_day.addEventListener('click',()=>shiftDay(-1)); els.next_day.addEventListener('click',()=>shiftDay(1));
els.language.addEventListener('change',()=>setLanguage(els.language.value));
els.theme_toggle.addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
els.city_search.addEventListener('keydown',event=>{ if(event.key==='Enter'){ event.preventDefault(); els.add_city.click(); } });
document.addEventListener('click',event=>{ if(!event.target.closest('.city-add-row')) els.city_suggestions.hidden=true; });
els.timeline.addEventListener('click',event=>{ const trackEl=event.target.closest('[data-track]'); if(!trackEl)return; const box=trackEl.getBoundingClientRect(); state.slot=Math.max(0,Math.min(47,Math.round(((event.clientX-box.left)/box.width)*48))); renderResults(); });
els.copy_result.addEventListener('click',async()=>{await navigator.clipboard.writeText(shareText()); els.copy_result.textContent=t('copied'); setTimeout(()=>els.copy_result.textContent=t('copy'),1200); track('result_copied');});
els.share_result.addEventListener('click',async()=>{const url=meetingUrl().href; const text=`${els.result_label.textContent}: ${els.results_title.textContent} — ${els.meeting_summary.textContent}`; if(navigator.share) await navigator.share({title:'Common Hours',text,url}); else await navigator.clipboard.writeText(`${text}\n\n${url}`); track('result_shared');});

const browserLanguage=(navigator.language||'en').slice(0,2); state.language=localStorage.getItem('commonHoursLanguage') || (copy[browserLanguage]?browserLanguage:'en');
state.date=new Date().toISOString().slice(0,10); restoreOrDetectReference(); els.meeting_date.value=state.date; els.duration.value=String(state.duration); applyTheme(localStorage.getItem('commonHoursTheme') || (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')); setLanguage(state.language); if(state.selected.length>=2){ if(state.restoredFromUrl) renderResults(); else calculate(); } else els.city_search.focus();


// Feedback dialog. Inert until index.html carries a Worker endpoint and a
// Turnstile site key; until then the footer link falls through to GitHub.
(function(){
  const link=document.querySelector('a[data-i18n="navFeedback"]');
  const dialog=document.getElementById('feedback-dialog');
  if(!link||!dialog) return;
  const endpoint=dialog.dataset.endpoint, sitekey=dialog.dataset.sitekey;
  if(!endpoint||!sitekey||typeof dialog.showModal!=='function') return;
  const form=dialog.querySelector('form'), status=dialog.querySelector('.feedback-status');
  const submit=form.querySelector('button[type="submit"]');
  let loaded=false, widgetId=null, openedAt=0;
  function loadTurnstile(){
    if(loaded) return; loaded=true;
    const s=document.createElement('script');
    s.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit'; s.async=true;
    s.onload=()=>{ if(window.turnstile) widgetId=turnstile.render('#feedback-turnstile',{sitekey}); };
    document.head.append(s);
  }
  link.addEventListener('click',event=>{
    event.preventDefault(); status.textContent=''; form.reset(); openedAt=Date.now();
    loadTurnstile(); if(widgetId!==null&&window.turnstile) turnstile.reset(widgetId);
    dialog.showModal();
  });
  dialog.querySelector('[data-feedback-cancel]').addEventListener('click',()=>dialog.close());
  form.addEventListener('submit',async event=>{
    event.preventDefault();
    const data=new FormData(form);
    const message=String(data.get('message')||'').trim().slice(0,2000);
    if(!message) return;
    const token=String(data.get('cf-turnstile-response')||'');
    if(!token){ status.textContent=t('fbError'); return; }
    const payload={message,cities:String(data.get('cities')||'').trim().slice(0,300),
      contact:String(data.get('contact')||'').trim().slice(0,200),website:String(data.get('website')||''),
      elapsed:Date.now()-openedAt,page:location.pathname,language:state.language,token};
    submit.disabled=true;
    try{
      const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
      if(!response.ok) throw new Error(String(response.status));
      status.textContent=t('fbThanks'); form.reset(); setTimeout(()=>dialog.close(),1400);
    }catch(error){
      status.textContent=t('fbError'); if(window.turnstile&&widgetId!==null) turnstile.reset(widgetId);
    }finally{ submit.disabled=false; }
  });
})();


// --- Day/night world map -----------------------------------------------------
// Deliberately draws NO time zone boundaries. Real borders are jagged and
// political (China spans five geographic bands on one zone; Nepal is +5:45), so
// a drawn band map would be approximate in a way that undercuts a site that
// hedges moon-sighting holiday dates for accuracy. This claims only two things,
// both exactly true: these cities are here, and it is night here.
// `var`, not `let`: renderResults() runs during page init - before this line is
// reached - whenever cities arrive from a shared link or localStorage, and a
// `let` here puts the cache in the temporal dead zone for exactly those paths.
var mapDataPromise=null;
function loadMapData(){
  if(!mapDataPromise){
    mapDataPromise=Promise.all([
      fetch('assets/world-land.json').then(r=>r.ok?r.json():null),
      fetch('assets/zone-points.json').then(r=>r.ok?r.json():null)
    ]).then(([land,zones])=>({land,zones})).catch(()=>({land:null,zones:null}));
  }
  return mapDataPromise;
}

// Subsolar point for a given instant. Ported from the standard low-precision
// solar position formulae and checked against the solstices and equinoxes:
// June gives declination +23.44 with the north pole lit, December reverses it.
function subsolarPoint(date){
  const n=(date.getTime()/86400000)+2440587.5-2451545.0;
  const rad=Math.PI/180;
  const L=(280.460+0.9856474*n)%360;
  const g=((357.528+0.9856003*n)%360)*rad;
  const lam=(L+1.915*Math.sin(g)+0.020*Math.sin(2*g))*rad;
  const eps=(23.439-0.0000004*n)*rad;
  const dec=Math.asin(Math.sin(eps)*Math.sin(lam))/rad;
  let raH=((Math.atan2(Math.cos(eps)*Math.sin(lam),Math.cos(lam))/rad)/15+24)%24;
  const gmst=((18.697374558+24.06570982441908*n)%24+24)%24;
  let lon=-15*(((gmst-raH)%24+24)%24);
  lon=((lon+180)%360+360)%360-180;
  return {dec,lon};
}

function cityPoint(city,zones){
  if(typeof city.lat==='number'&&typeof city.lon==='number') return [city.lat,city.lon];
  const z=zones&&(zones[city.zone]||zones[canonicalZone(city.zone)]);
  return z?[z[0],z[1]]:null;
}

function renderWorldMap(){
  const figure=document.getElementById('world-map-figure');
  const svg=document.getElementById('world-map');
  if(!figure||!svg) return;
  // shown from the first city: it is the only visual on the page, and gating it
  // behind a second city meant a first-time visitor never saw it at all
  if(state.selected.length<1){ figure.hidden=true; return; }
  loadMapData().then(({land,zones})=>{
    if(!land||!land.paths){ figure.hidden=true; return; }
    const desc=svg.querySelector('desc');
    const parts=[];
    parts.push('<rect class="ocean" x="0" y="0" width="360" height="180"/>');
    parts.push('<g class="land">'+land.paths.map(d=>'<path d="'+d+'"/>').join('')+'</g>');

    // Night polygon: sample the terminator every 2 degrees of longitude, then
    // close it along whichever pole edge is in darkness.
    const {dec,lon:sslon}=subsolarPoint(new Date());
    const decR=(Math.abs(dec)<1e-6?(dec>=0?1e-6:-1e-6):dec)*Math.PI/180;
    const pts=[];
    for(let lon=-180;lon<=180;lon+=2){
      const h=(lon-sslon)*Math.PI/180;
      const lat=Math.atan(-Math.cos(h)/Math.tan(decR))*180/Math.PI;
      pts.push([lon+180,90-lat]);
    }
    // dec > 0 means the northern hemisphere is tilted sunward, so the dark cap
    // is the southern one (y = 180 edge), and vice versa.
    const edgeY=dec>0?180:0;
    const d='M'+pts.map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join('L')
            +'L360 '+edgeY+'L0 '+edgeY+'Z';
    parts.push('<path class="night" d="'+d+'"/>');

    // City pins. Labels nudge vertically when they would collide.
    const placed=[];
    state.selected.forEach((city,index)=>{
      const pt=cityPoint(city,zones);
      if(!pt) return;
      const x=pt[1]+180, y=90-pt[0];
      let ly=y-4;
      while(placed.some(p=>Math.abs(p.x-x)<44&&Math.abs(p.y-ly)<7)) ly-=7;
      placed.push({x,y:ly});
      const anchor=x>300?'end':(x<60?'start':'middle');
      const lx=x>300?x-3:(x<60?x+3:x);
      parts.push('<circle class="pin'+(city.detected?' pin-you':'')+'" cx="'+x.toFixed(1)+
                 '" cy="'+y.toFixed(1)+'" r="2.6"/>');
      parts.push('<text class="pin-label" x="'+lx.toFixed(1)+'" y="'+ly.toFixed(1)+
                 '" text-anchor="'+anchor+'">'+escapeHtml(city.name)+'</text>');
    });
    svg.innerHTML=(desc?desc.outerHTML:'')+parts.join('');
    figure.hidden=false;
  });
}

function escapeHtml(v){
  return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
